 Q(3,'Dönüşüm','"After I had read the letter, I tore it up." Aynı anlam hangisi?','Having read the letter, I tore it up.',['Having reading the letter, I tore it up.','Read the letter, I tore it up.'],'having + V3.'),
 Q(3,'Dönüşüm','"Because the book was written for children, it is easy." Aynı anlam hangisi?','Written for children, the book is easy.',['Writing for children, the book is easy.','Having writing for children, the book is easy.'],'Edilgen: V3.'),
 Q(3,'Dönüşüm','"As I didn\'t want to be late, I took a taxi." Aynı anlam hangisi?','Not wanting to be late, I took a taxi.',['Not wanted to be late, I took a taxi.','Wanting not be late, I took a taxi.'],'Not + -ing.'),
 Q(3,'Karışık','Hangi cümle doğru?','Seen from the hill, the village looks beautiful.',['Seeing from the hill, the village looks beautiful.','Having seeing from the hill, the village looks beautiful.'],'Köy görülüyor: V3.'),
 Q(3,'Karışık','Hangi cümle doğru?','Anyone caught cheating will be disqualified.',['Anyone catching cheating will be disqualified.','Anyone caught to cheat will be disqualified.'],'who is caught → caught + -ing.'),
 Q(4,'Özne','Hangi cümle YANLIŞ (özneler uyuşmuyor)?','Running for the bus, my phone fell out of my pocket.',['Running for the bus, I dropped my phone.','While I was running for the bus, my phone fell out of my pocket.'],'Koşan telefon değil: özne aynı olmalı.'),
 Q(4,'Özne','Hangi cümle doğru?','Arriving at the station, we found that the train had left.',['Arriving at the station, the train had already left.','Arrived at the station, we found that the train had left.'],'Biz vardık: özne we, -ing.'),
 Q(4,'Karışık','Hangi cümle doğru?','Having been told the news, she called her parents.',['Having told the news, she called her parents.','Being told the news before, she called her parents.'],'Ona söylendi ve önce oldu: having been + V3.'),
